/**
 * THE ROUTE TABLE. One row per screen, in navigation order.
 *
 * Screen agents: DO NOT EDIT THIS FILE to build your screen. Your screen already
 * has a row here. Touch this table only to change a path, a nav group, an icon
 * or a role requirement, and say so in your report.
 *
 * `titleKey` / `navKey` are catalog keys (packages/config/locales/{tr,en}.json).
 * Every one of them must exist in BOTH locales or the app throws on render;
 * test/i18n.test.tsx asserts that for the whole table.
 */

/**
 * Six groups, ordered by how an operator actually works:
 *
 *   start       İşler      — the daily list and the live sessions
 *   ai          Ajanlar    — the agent definitions and what they learn from
 *   projects    Projeler   — binding Jira projects and repositories
 *   compliance  Denetim    — audit trail, PII, AI usage, evidence
 *   admin       Yönetim    — connections, notifications, parameters, users, health
 *   help        Yardım
 *
 * "Kurulum" used to hold the wizard AND five administration screens; the wizard
 * now lives with the projects it configures, administration has its own group.
 */
export type NavGroup = "start" | "ai" | "projects" | "compliance" | "admin" | "help";

export interface ScreenDef {
  /** Matches the mock's view id; also the component's file name, lowercased. */
  readonly id: string;
  /** Route path relative to the shell root, without a leading slash. */
  readonly path: string;
  /** Catalog key for the page heading. */
  readonly titleKey: string;
  /** Catalog key for the sidebar label; absent means "not in the sidebar". */
  readonly navKey?: string;
  readonly group?: NavGroup;
  /** Glyph shown before the sidebar label. */
  readonly icon?: string;
  /**
   * Roles that may SEE this entry in the navigation. Empty/absent = everyone.
   * This is a usability filter, NOT access control — the BFF authorises every
   * request regardless of what the sidebar shows (RequireSession.tsx). Every
   * value here mirrors the BFF route's own role check, so an operator is not
   * offered a page that would only 403.
   */
  readonly roles?: readonly string[];
}

export const NAV_GROUPS: readonly NavGroup[] = [
  "start",
  "ai",
  "projects",
  "compliance",
  "admin",
  "help",
];

export const NAV_GROUP_KEY: Readonly<Record<NavGroup, string>> = {
  start: "nav.group.start",
  ai: "nav.group.ai",
  projects: "nav.group.projects",
  compliance: "nav.group.compliance",
  admin: "nav.group.admin",
  help: "nav.group.help",
};

/** BFF role vocabularies the menu mirrors (apps/bff: requireRole / requireAnyRole). */
