/** `login` lives outside the shell (no sidebar, no session) — see routes.tsx. */
export const LOGIN_SCREEN: ScreenDef = {
  id: "login",
  path: "/login",
  titleKey: "screen.login.title",
};

export const ALL_SCREEN_IDS: readonly string[] = [
  ...SCREENS.map((screen) => screen.id),
  LOGIN_SCREEN.id,
];

export function screenById(id: string): ScreenDef | undefined {
  if (id === LOGIN_SCREEN.id) return LOGIN_SCREEN;
  return SCREENS.find((screen) => screen.id === id);
}
